CREATE TABLE tenants(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE stores(code TEXT PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,verification_note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE hq_members(tenant_id INTEGER NOT NULL REFERENCES tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE store_grants(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),store TEXT NOT NULL REFERENCES stores(code),role TEXT NOT NULL CHECK(role IN ('staff','manager','admin')),job TEXT NOT NULL,stations TEXT NOT NULL,note TEXT NOT NULL,expires_at TEXT NOT NULL,granted_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,revoked_at TEXT,UNIQUE(user_id,store));
CREATE TABLE store_transfers(id INTEGER PRIMARY KEY,store TEXT NOT NULL REFERENCES stores(code),source_tenant INTEGER NOT NULL REFERENCES tenants(id),destination_tenant INTEGER NOT NULL REFERENCES tenants(id),requested_by INTEGER NOT NULL REFERENCES users(id),note TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','rejected')),decision_note TEXT,decided_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,decided_at TEXT);
CREATE UNIQUE INDEX pending_transfer ON store_transfers(store) WHERE state='pending';
CREATE TABLE hq_templates(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),template_id INTEGER REFERENCES hq_templates(id),version INTEGER NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,source TEXT NOT NULL,change_note TEXT NOT NULL,risk INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','review','published')),created_by INTEGER NOT NULL REFERENCES users(id),approved_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,approved_at TEXT,UNIQUE(template_id,version));
CREATE TABLE hq_deliveries(id INTEGER PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES tenants(id),template_version_id INTEGER NOT NULL REFERENCES hq_templates(id),store TEXT NOT NULL REFERENCES stores(code),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','rejected')),note TEXT NOT NULL DEFAULT '',local_revision_id INTEGER REFERENCES revisions(id),difference_note TEXT NOT NULL DEFAULT '',sent_by INTEGER NOT NULL REFERENCES users(id),signed_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,signed_at TEXT,sign_hash TEXT,UNIQUE(template_version_id,store));
CREATE TABLE hq_adoptions(tenant_id INTEGER NOT NULL REFERENCES tenants(id),store TEXT NOT NULL REFERENCES stores(code),template_id INTEGER NOT NULL REFERENCES hq_templates(id),document_id INTEGER NOT NULL REFERENCES documents(id),last_delivery_id INTEGER NOT NULL REFERENCES hq_deliveries(id),PRIMARY KEY(store,template_id));
CREATE TABLE work_tasks(id INTEGER PRIMARY KEY,store TEXT NOT NULL REFERENCES stores(code),station TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,owner_id INTEGER NOT NULL REFERENCES users(id),due_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')),evidence TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,closed_by INTEGER REFERENCES users(id),closed_at TEXT,version INTEGER NOT NULL DEFAULT 1,source_kind TEXT NOT NULL,source_id TEXT NOT NULL,UNIQUE(store,source_kind,source_id));
CREATE TABLE agent_plans(id INTEGER PRIMARY KEY,store TEXT NOT NULL REFERENCES stores(code),station TEXT NOT NULL,title TEXT NOT NULL,recipe_revision_id INTEGER NOT NULL REFERENCES revisions(id),launch_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','review','approved','executed','cancelled')),version INTEGER NOT NULL DEFAULT 1,inputs TEXT NOT NULL,tasks TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),approved_by INTEGER REFERENCES users(id),approval_note TEXT,created_at TEXT NOT NULL,approved_at TEXT,executed_at TEXT);
CREATE TABLE business_requests(actor INTEGER NOT NULL REFERENCES users(id),store TEXT NOT NULL,action TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(actor,store,action,key));
CREATE TABLE agent_tool_events(id INTEGER PRIMARY KEY,store TEXT NOT NULL,actor INTEGER NOT NULL REFERENCES users(id),plan_id INTEGER REFERENCES agent_plans(id),tool_name TEXT NOT NULL,request_hash TEXT NOT NULL,outcome TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER immutable_hq_template BEFORE UPDATE ON hq_templates WHEN OLD.state<>'draft' AND (NEW.content<>OLD.content OR NEW.title<>OLD.title OR NEW.kind<>OLD.kind OR NEW.source<>OLD.source OR NEW.change_note<>OLD.change_note OR NEW.risk<>OLD.risk OR NEW.version<>OLD.version OR NEW.template_id IS NOT OLD.template_id OR NEW.tenant_id<>OLD.tenant_id) BEGIN SELECT RAISE(ABORT,'Submitted HQ template is immutable'); END;
CREATE INDEX task_queue ON work_tasks(store,station,state,due_at);
CREATE INDEX agent_queue ON agent_plans(store,station,state);
